We consider $\RR^d$ endowed with a general norm $\norm{\,\cdot\,}$, and denote by $\norm{x}_2$ the standard Euclidean norm, {\em i.e.} $\norm{x}_2^2 = \sum_{i=1}^d x_i^2$. In what follows,  $T:\RR^d \to \RR^d$ is such that
\[
\norm{Tx-Ty} \le \gamma\norm{x-y}, \qquad \forall x,y\in \RR^d.
\]
We say that $T$ is a contraction if $\gamma \in (0, 1)$, and that $T$ is nonexpansive if $\gamma = 1$. We assume that in the nonexpansive case $\Fix \, T \neq \emptyset$, where $\Fix\, T$ stands for the set of fixed-points of $T$. We are interested in computing an approximate solution of the fixed-point equation $x=Tx$.


where $(\beta_n)_n$ is a nondecreasing stepsize sequence satisfying $0< \beta_n <1$, $\lim_{n \to \infty}\beta_n=1$, and $x^0 \in \RR^d$ is an arbitrary initial condition.  It is worth mentioning that the original Halpern iteration uses an arbitrary $u$ called {\em the anchoring point} that can be different from the initial point $x^0$. In that case, the iteration reads $x^{n} = (1-\beta_{n})u + \beta_{n}Tx^{n-1}$. We assume here, without loss of generality, that the anchoring point is exactly $x^0$.


\begin{assumption} \label{assumption1} 
    The access to the operator $T$ occurs through a stochastic oracle $\tilde{T}: \RR^d\times \Xi \to \RR^d$ which is an unbiased approximation of $T$ in the sense that 
\begin{equation*}
    \EE(\tilde{T}(x,\xi)) = Tx \qquad \mbox{for all $x\in \RR^d$},
\end{equation*}
with $\xi$ drawn from some distribution $\mathcal D_x$ over $\Xi$. Additionally, we assume that $\EE \left(||\tilde{T}(x,\xi)-Tx||^2_2\right)$ is finite for every $x \in \RR^d$.
\end{assumption}

We say that the oracle $\tilde T$ has {\em uniformly bounded variance} (with bound $\sigma^2)$ if there exists a positive constant $\sigma^2$ such that
\begin{equation*}
 \sup_{x \in \RR^d}\EE \left(\norm{\tilde{T}(x,\xi)-Tx}^2_2\right)\leq \sigma^2.
\end{equation*}


\begin{equation}
    x^{n} = (1-\beta_{n})x^0 + \beta_{n}(Tx^{n-1} + U_{n}), \quad \forall \, n \geq 1,
    \label{halpern}
    \tag{$\textsc{iH}$}
\end{equation}

where $U_n$ is such that $\EE(U_n)=0$ and the term $\EE(\norm{U_n})$ can be controlled appropriately. It is worth noting that we do not assume further properties on the stochastic oracle in order to maintain our results as general as possible. See Section~\ref{sec:method} for a precise definition and related discussions. 


We are interested in the problem of estimating the oracle complexity to find an approximate fixed-point of $T$, which is measured as the number of calls to the vector stochastic oracle $\tilde T$. In the case where $T$ is nonexpansive, we estimate the oracle complexity to find a last-iterate approximate solution $x^n$ in the sense that the expected fixed-point residual $\EE (\norm{x^n - Tx^n})$ is smaller than a given tolerance. For a contracting operator $T$, we aim to find oracle complexity bounds for the expected distance of the last iterate $x^n$ to the unique fixed-point $x^*$, {\em i.e.} the quantity $\EE (\norm{x^n - x^*})$.


\noindent {\bf Notation.} Let us set some basic notation that we use in this paper.  Given that all norms in $\RR^d$ are equivalent, let $\mu > 0$ be such that $\norm{x} \le \mu \norm{x}_2$ for all $x\in \RR^d$ and we denote by $\norm{x}_{\text{sp}}=\max_{i}x_i - \min_{i}x_i$ the so-called span seminorm of $x$.

We adopt the standard big-$O$ notation, that is, for two real functions $f,g:$ we say $f(x)=O(g(x))$ if there are two constants $C$ and $c$ such that $f(x)\leq C g(x)$ for all $x\geq c$. We use $\tilde O$ if we ignore logarithmic factors. Analogously, $f(x)=\Omega(g(x))$ if $f(x)\geq C g(x)$ for all $x\geq c$.


Algorithm~\ref{alg_stochastic_halpern} outlines the stochastic Halpern iteration with minibatches. At each iteration $n \leq N$, a minibatch estimator is constructed with $k_n$ queries to $\tilde T$ at $x^{n-1}$ using $k_n$ independent fresh samples from $\mathcal D_{x^{n-1}}$. Using this estimate, the next iterate is calculated via the Halpern iteration. 


\begin{algorithm}[H]
\caption{Stochastic Halpern method}
\label{alg_stochastic_halpern}
\begin{algorithmic}[1]
\Require Stochastic oracle $\tilde{T}$, $(k_n)_n$ minibatch size sequence, number of iterations $N$, initial point $x^0$    
\For{$n=1,\dots, N$}
\State Set the size of the minibatch $k_n$ 
\State Sample $k_n$ independent queries at $x^{n-1}$: $\tilde{T}(x^{n-1}, \xi^n_{1}), \dots, \tilde{T}(x^{n-1}, \xi^n_{k_n})$.    
\State Set
$x^n \leftarrow (1-\beta_n)x^0 + \beta_n\left(\frac{1}{k_n}\displaystyle{\sum_{j=1}^{k_n}} \tilde{T}(x^{n-1}, \xi^n_{j})\right)$
\EndFor
\State Return $x^N$
\end{algorithmic}
\end{algorithm}

Notice that if we define the error term at the iteration $n \geq 1$  by 
\begin{equation*}
U_n := \frac{1}{k_n}\displaystyle{\sum_{j=1}^{k_n}} \tilde{T}(x^{n-1}, \xi^n_{j}) - Tx^{n-1},
\end{equation*}
then Algorithm~\ref{alg_stochastic_halpern} can be cast in the form \eqref{halpern}. Indeed, we will refer to both procedures indistinctly when there is no confusion.

By construction, $Tx^{n-1} + U_n$ is an unbiased estimator of $Tx^{n-1}$ and may have a reduced variance compared to the error computed with a single query. 


\begin{equation}    \label{notation_beta_sigma}
\left \{
\begin{aligned} 
    &\sigma_n:=\EE(\norm{U_n})\,\,\, \text{and}\,\,\,\sigma_0=\beta_0=0;\\
    & B_i^n:= \prod_{j=i}^n \beta_j, \,\,\,\text{with the convention}\,\,\,  B_{i}^n=1 \,\,\, \text{if}\,\,\,  0\leq n<i.
    \end{aligned}
    \right.
\end{equation}

\begin{equation}\tag{$\textsc{H}_1$} \label{H1}
\text{There exists } \overline \kappa <+\infty \, \text{ such that }\, \sup \nolimits_{n \geq 0}\EE (\norm{T x^n-x^0}) \leq \overline \kappa < +\infty.
\end{equation}

The following corollary provides an upper bound on the number of queries for the stochastic Halpern iteration with minibatching when the stochastic oracle has uniformly bounded variance. Due to Lemma~\ref{lem:sigma_explicito}, the constants involved can be explicitly estimated in this case. For the sake of simplicity, we assume in what follows that $\varepsilon>0$ is sufficiently small.

