proof.raw_tex:
For the sake of completeness, we recall how a standard argument allows to transfer the variance reduction into a bound on $\sigma_n$. 

For a given iteration $n$, let $\xi^n_{1},\ldots,\xi^n_{k_n}$ be $k_n$ independent samples of the distribution $\mathcal D_{x^{n-1}}$ and let $e_n^2=\EE (||\tilde{T}(x^{n-1}, \xi^n_{1}) - T x^{n-1}||_2^2)$ be the variance of the error term of one query. Then
\begin{equation}
\sigma_n^2=\EE(\norm{U_n})^2 \le \frac{\mu^2}{k_n^2} \EE\left(\norm{\sum \nolimits_{j=1}^{k_n} \tilde{T}(x^{n-1}, \xi^n_{j}) - Tx^{n-1} }^2_2\right) \le \frac{\mu^2}{k_n}e_n^2,
\label{minibatch}
\end{equation}
where we have use Jensen's inequality, sample independence, and the equivalence between the norms. We observe that $\EE(\norm{U_n})$ scales by a factor $\frac{\mu}{\sqrt{k_n}}$ compared to $e_n$.  


\begin{proposition} \label{prop:residual-nonexpansive}
Let $(x^n)_{n\ge 1}$ the sequence generated by the Halpern iteration \eqref{halpern}. Assume that \eqref{H1} holds for some $\overline \kappa \geq 0$. Then, for all $n\ge 1$
\[
\EE(\norm{x^n-Tx^n}) \le \overline\kappa(1-\beta_n) + \sum_{i=1}^{n} B_i^n \left(\overline\kappa(\beta_i -\beta_{i-1}) + \beta_i\sigma_i+\beta_{i-1}\sigma_{i-1} \right )+ \beta_n\sigma_n,
\]
where $B^n_i$ and $\sigma_i$ are defined in \eqref{notation_beta_sigma}.
\end{proposition}

\begin{proof}
Recall that $\sigma_0=\beta_0=0$ and let $\kappa_n= \norm{Tx^n-x^0}$. We start by observing that the (random) sequence $(P_n)_n$ defined inductively as $P_0=0$ and
\[ P_n=
\kappa_{n-1} (\beta_n-\beta_{n-1})+\beta_{n-1} P_{n-1}+\beta_n\norm{U_n}+\beta_{n-1}\norm{U_{n-1}},\,\,  n\geq 1,
\]
is such that $\norm{x^n-x^{n-1}}\leq P_n$ for all $n \in \NN$. Indeed, for the first term we write
\[
\norm{x^1-x^0}= \beta_1\norm{x^0 -Tx^0 + U_1} \leq \kappa_0 (\beta_1-\beta_0) + \beta_1 \norm{U_1}=P_1.
\]
From the definition of \eqref{halpern}, using again the triangular inequality, the nonexpansivity of $T$, and the induction hypothesis, we have that for $n \geq 2$,
\begin{equation*}
\begin{aligned}
\!\!\norm{x^n\!-\!x^{n-1}} &=\norm{(1\!-\! \beta_{n}) x^0 + \beta_n(Tx^{n-1} +U_n)-(1\!-\!\beta_{n-1})x^0 \!-\! \beta_{n-1}(Tx^{n-2} +U_{n\!-\!1})}\\
&=\norm{(\beta_{n}\!-\!\beta_{n-1})(T x^{n-1}\!-\!x^0)\! + \!\beta_{n-1}(Tx^{n-1}\!\!-Tx^{n-2}) \!+\!\beta_{n} U_n\!-\!\beta_{n-1}U_{n-1}} \\
&\leq (\beta_n-\beta_{n-1})\norm{T x^{n-1}\!-\!x^0}\!+\! \beta_{n-1}\norm{x^{n-1}\!-\!x^{n-2}}\!+\!\beta_n\norm{U_{n}}\!+\!\beta_{n-1}\norm{U_{n-1}} \\
&\le \kappa_{n-1} (\beta_n-\beta_{n-1})+\beta_{n-1} P_{n-1}+\beta_n\norm{U_{n}}\!+\!\beta_{n-1}\norm{U_{n-1}}=P_n.
\end{aligned}
\end{equation*}

Then, it follows that $P_n$ can be computed explicitly as
\[
P_n=\sum_{i=1}^{n}B_i^{n-1} \left ( \kappa_{i-1}(\beta_i -\beta_{i-1}) + \beta_i\norm{U_{i}}+\beta_{i-1}\norm{U_{i-1}} \right ).
\]
where we used the convention $B^{n-1}_n = 1$. Now, casting \eqref{halpern} as
   \[
    x^{n} - Tx^n = (1-\beta_{n})(x^0-Tx^{n}) + \beta_{n} (Tx^{n-1}-Tx^n + U_{n}), \quad \forall \, n \geq 1,
   \]
we get that 
\begin{equation}\label{eq:residual}
\begin{aligned}
\!\!\!\norm{x^n-\!Tx^n} & \!\!=\! \!\norm{(1\!-\!\beta_n)(x^0-Tx^{n})+\beta_n(Tx^{n-1}-Tx^n+U_n )} \\
&\le \kappa_n (1-\beta_n) +  \beta_n  \norm{x^n-x^{n-1}}+ \beta_n\norm{U_n} \\
&\leq \kappa_n(1-\beta_n) +  \beta_n  P_n+ \beta_n\norm{U_n},\\
& = \kappa_n(1-\!\beta_n)\! +\! \\
&+\sum_{i=1}^{n}B_i^{n}\left ( \!\kappa_{i-1}(\beta_i -\beta_{i-1})\! + \!\beta_i\norm{U_i}\!\!+\!\!\beta_{i-1}\norm{U_{i-1}} \!\right )+ \beta_n\norm{U_n}
\end{aligned}
\end{equation}
where we used that $B^n_i = \beta_nB^{n-1}_i$ for every $i=1,...,n$ and that $B^{n-1}_{n} = 1$. Taking expectations in the expression above, and using that $\sigma_i = \EE(\norm{U_i})$, we obtain
\begin{equation*}
\begin{aligned}
\EE(\norm{x^n\!\!-\!\!Tx^n}) &\leq \EE(\kappa_n)(1-\!\beta_n)+ \sum_{i=1}^{n}B_i^{n}\left ( \EE(\kappa_{i-1})(\beta_i -\beta_{i-1})\! + \!\beta_i\sigma_i +\beta_{i\!-\!1}\sigma_{i-1} \!\right )\!+\! \beta_n\sigma_n. 
\end{aligned}
\end{equation*}
The conclusion follows from the fact that $\sup_{n\geq 0} \EE(\kappa_n) \leq \overline \kappa$.
\end{proof}

\begin{lemma} \label{lem:kappa}
{\em Let $T$ be nonexpansive and $(x^n)_n$ be the sequence generated by \eqref{halpern}. Recalling the notation \eqref{notation_beta_sigma}, it holds:
\begin{itemize}
    \item[$(i)$] If $T$ has bounded range i.e. there exist a constant $M>0$ such that $\norm{Tx} \le M$ for all $x\in \RR^d$, then the condition \eqref{H1} holds with $\bar \kappa = M + \norm{x^0}$.
    \item[$(ii)$] If the sequences $(\beta_n)_n$ and $(\sigma_n)_n$ satisfies
    \begin{equation}\label{H2}\tag{$\textsc{H}_2$}
    \sup_{n\ge 1}\sum_{i=1}^n B_i^n\sigma_i\leq S < +\infty,,
    \end{equation}
    for some $S\ge 0$, then condition \eqref{H1} holds with $\bar \kappa = 2\dist(x^0, \Fix(T)) + {S}$. 

    In particular, if $\sum_n \sigma_n <+\infty$ then  \eqref{H2} holds. 
\end{itemize}
}
\end{lemma}

\begin{proof} 
Part $(i)$ follows from the triangular inequality. For part $(ii)$, let us fix $x^*\in \Fix(T)$. Using the fact that $T$ is nonexpansive we have
\begin{align}
    \norm{x^n-x^*} & = \norm{(1-\beta_n)(x^0-x^*) + \beta_n(Tx^{n-1}-x^*) + \beta_nU_n} \nonumber \\
    & \le (1-\beta_n)\norm{x^0-x^*} + \beta_n \norm{x^{n-1}-x^*} + \beta_n\norm{U_n} \nonumber \\
    &=\sum_{i=0}^n B^n_{i+1}( \norm{x^0-x^*}(1-\beta_i)+\beta_i\norm{U_n})\nonumber  \\
    &=  \norm{x^0-x^*} + \sum_{i=1}^n B^n_i \norm{U_i}, \label{eq:bounded}
\end{align}

where we used $\sum_{i=0}^n B^n_{i+1}(1-\beta_i)=1$ and the convention $B^n_{n+1} = 1$. Taking expectations, we have
\begin{equation*}
\begin{aligned}
\EE(\norm{Tx^n-x^0})&\le \EE(\norm{Tx^n-Tx^*})+\norm{x^*-x^0}\\
&\le 2 \norm{x^*-x^0} + \sum_{i=1}^n B_i^n\sigma_i \leq  2 \norm{x^*-x^0}+ S.
\end{aligned}
\end{equation*}
Finally, $\sup_{n \geq 0}\EE(\norm{Tx^n-x^0})\leq 2\inf_{x^* \in \Fix T}\norm{x^*-x^0} +S.$
\end{proof}

\begin{theorem} \label{thm:rate-nonexpansive}
 Let $(x^n)_n$ be the sequence generated by the Halpern iteration~\eqref{halpern} with the stepsize $\beta_n=\frac{n}{n+1}$. Assume that \eqref{H1} holds for some $\overline \kappa \geq 0$ and that $\sigma_n= \EE(\norm{U_n})$ is such that $\sum_{n=1}^N n\sigma_n =\tilde O(1)$. Then, given $\varepsilon>0$,  $\EE(\norm{x^N-Tx^N})\le \varepsilon$ for all $N \geq \bar N= \tilde{O}(\varepsilon^{-1})$ iterations.
\end{theorem}

\begin{proof}
For this particular choice of $\beta_n$, we have that $B_i^n=\frac{i}{n+1}$ for all $1 \leq i\leq n$. Then 
\[
S = \sup_{N\geq 1}\sum_{n=1}^N B_n^N  \sigma_n= \sup_{N\geq 1}\frac{1}{N+1}\sum_{n=1}^N n \sigma_n< \infty, 
\]
given that $\sum_{n= 1}^N n \sigma_n = \tilde{O}(1)$ and we conclude that \eqref{H2} holds and \eqref{H1} is satisfied with $\bar \kappa=S+2\dist(x^0, \Fix T)$. Now, invoking the estimates given by Proposition~\ref{prop:residual-nonexpansive} 
\begin{equation} \label{bound-expected-nonexpansive} 
\begin{aligned}
 \!\!\! \EE(\norm{ x^N-Tx^N }) & \le \! \frac{\bar{\kappa}}{N\!+\!1} \!+\!  \frac{1}{N\!+\!1}\sum_{n=1}^N \left( \frac{\bar{\kappa}}{n\!+\!1} \!+\! \frac{n^2}{n\!+\!1}\sigma_n \!+\!(n\!-\!1)\sigma_{n-1} \right ) \!+\!\frac{N}{N\!+\!1}\sigma_N\\
&=\frac{1}{N\!+\!1}\left(\bar{\kappa}\sum_{n=0}^{N}\frac{1}{n\!+\!1}  \!+\!\sum_{n=1}^N\frac{n^2}{n\!+\!1}\sigma_n +\sum_{n=2}^N(n\!-\!1)\sigma_{n-1}+ N \sigma_N\right )\\
  &\le\frac{\bar{\kappa}}{N\!+\!1}\sum_{n=0}^{N}\frac{1}{n\!+\!1}+\frac{2}{N\!+\!1}\sum_{n=1}^N n\sigma_n - \frac{1}{N+1}\sum_{n=1}^N \sigma_n,
\end{aligned}
\end{equation}
where we have used in the second line that $\sigma_0=0$. We observe that the first term $\tilde{O}(1/N)$ and the second also is by hypothesis. Therefore, $\EE(\norm{x^N-Tx^N}) = \tilde{O}(1/N)$, and $\EE(\norm{ x^N-Tx^N }) \le \varepsilon$, for all $N \geq \bar N= \tilde{O}(\varepsilon^{-1})$ iterations as claimed.
\end{proof}

\begin{lemma}\label{lem:sigma_explicito}
Under the assumptions of Theorem~\ref{thm:rate-nonexpansive}, let us suppose additionally that there exists $C\geq 0$ such that $\sum_{n=1}^N n\sigma_n \leq C \ln(N+1)$ for all $N \geq 1$. Let $\rho \geq 0$ such that $3\bar{\kappa} + 2C\leq \rho$. Then, for all $\varepsilon>0$, if $\varepsilon/\rho < e^{-1}$, then 
\[
\EE(\norm{x^N-Tx^N})\le \varepsilon \quad \text{for all }\,\, N \geq \mbox{$\left \lceil 2\frac{\rho}{\varepsilon} \ln\left (\frac{\rho}{\varepsilon}\right )\right \rceil$} .
\]
When $\varepsilon/\rho \geq e^{-1}$, then $N=1$ iteration is sufficient.
\end{lemma}

\noindent {\em Proof.} Equation~\eqref{minibatch} guarantees that 
 $\sigma_n\le \mu\sigma{n^{-2}},$ 
 which readily implies that
 $$\sum_{n=1}^N n\sigma_n\leq \mu\sigma\sum_{n=1}^N \frac{1}{n}\leq \frac{3}{2}\mu\sigma\ln(N+1).$$ 
 Recalling that for this particular choice of $\beta_n$, $B_i^n= \frac{i}{n+1}$, $i=1,\ldots,n$, we have that
 \[
\sum_{i=1}^n B_i^n\sigma_i=\frac{1}{n+1} \sum_{i=1}^n i \sigma_i\leq \mu\sigma\frac{1}{n+1}\sum_{i=1}^n \frac{1}{i} \leq \frac{\mu\sigma}{2}.
 \]
 Therefore, condition~\eqref{H2} holds with $S= \mu\sigma/2$ and, from Lemma~\ref{lem:kappa}$(ii)$,  \eqref{H1} is verified with $\bar \kappa= \mu\sigma/2 + 2 \dist(x^0, \Fix T)$.  Then, using Lemma~\ref{lem:sigma_explicito} with $C=\frac{3}{2}\mu\sigma$ implies that $\EE(\norm{x^N-Tx^N})\le \varepsilon$ for all $N$ larger that $ \bar N= \left \lceil 2\frac{\rho}{\varepsilon} \ln\left (\frac{\rho}{\varepsilon}\right )\right \rceil $, with \vspace{-1ex}
 $$\frac{9}{2}\mu\sigma+6 \dist(x^0, \Fix T)\leq 12 \max \{\mu\sigma,\dist(x^0, \Fix T)\}:=\rho.$$ Finally, as each iteration $n=1,...,\bar N$ requires $n^4$ queries to the stochastic oracle, the overall oracle complexity to achieve precision $\varepsilon>0$ is 
 $$ \qquad \qquad \qquad \qquad \qquad \qquad  \sum_{n=1}^{\bar N} k_n = \sum_{n=1}^{\bar N} n^{4} \le \frac{(\bar N+1)^5}{5}\leq \frac{32}{5} \left (\frac{\rho}{\varepsilon}\ln\left (\frac{\rho}{\varepsilon}\right ) +1\right )^5. \qquad \qquad \qquad \qquad \qquad  \,\, \QEDA$$


\subsection{Proof of Lemma~\ref{lem:sigma_explicito}} \label{apx:explicito}
Assuming that $\sum_{n=1}^N n\sigma_n \leq C \ln(N+1)$, the bound \eqref{bound-expected-nonexpansive} implies that
\begin{equation*} 
\EE(\norm{ x^N-Tx^N}) \le \frac{1}{N+1}\left( 3\bar{\kappa}+2C\right)\ln(N+1) \le \underbrace{(3\bar{\kappa} + 2C)}_{\leq\rho}\frac{\ln(N+1)}{N+1}, \end{equation*}
where we have used the rough bound $3\ln(N+1)\geq \sum_{n=1}^{N+1}\frac{1}{n}$ for all $N \geq 1$, in order to keep the estimates simple at the expense of some small factor. 



For $\varepsilon>0$, let us call $\tau:=\frac{\varepsilon}{\rho}>0$. It is sufficient to find some $\bar N\in \NN$ such that, for any $N \geq \overline{N}$,
\[
\frac{\ln(N+1)}{N+1} \leq \tau, \quad \text{or, equivalently,}\,\, -\tau (N+1)e^{-\tau(N+1)}\geq -\tau.
\]
First, note that if $\tau \geq e^{-1}$ then the inequality above holds for all $N \geq 0$. We assume in what follows that $\tau < e^{-1}$. 



It is well-known that if we want to solve the equation $-\tau (x+1)e^{-\tau(x+1)}= -\tau$, the solution is given by the relation $-\tau(x+1) = W(-\tau)$, where $W$ is the Lambert function. Given that $\tau >0$, there is two solutions of this equation, provided by the upper and lower branches of $W$, $W_0$ and $W_{-1}$, respectively. We recall that both functions are continuous, defined in the interval $[-e^{-1},0]$, and such that $W_0(-e^{-1})=W_{-1}(-e^{-1})=-1$, $W_0$ increases to cero and $W_{-1}$ decreases to $-\infty$. This implies 
that for all $\tau \in (0,e^{-1})$, $W_0(-\tau) \in (-1,0)$ and that $W_{-1}(-\tau) \in (-\infty, -1)$. Let us pick the solution given by the lower branch, i.e. the one such that $x+1\geq \tau^{-1}$. In that case, 
$$x= -\frac{1}{\tau}W_{-1}(-\tau)-1.$$
Therefore if we set $m=\lceil -\frac{1}{\tau}W_{-1}(-\tau) -1 \rceil \in \NN$ we obtain that 
$$\frac{\ln(N+1)}{N+1} \leq \tau, \quad \text{for all } N\in \NN, N\geq m.$$
Let us show that  $m \leq \lceil 2\frac{\rho}{\varepsilon} \ln\left (\frac{\rho}{\varepsilon}\right ) \rceil= \lceil \frac{2}{\tau} \ln\left (\frac{1}{\tau}\right ) \rceil$. For that purpose, we use following lower bound for the function $W_{-1}$ (see \cite[Theorem 1]{chatzigeorgiou2013bounds}):

$$W_{-1}(-e^{-u-1}) \geq -1-\sqrt{2u}-u, \quad \text{for all} \, u>0.$$ 

Taking $u=-\ln(\tau)-1>0$, we get that $-e^{-u-1}=-\tau$ and hence
\[
\begin{aligned}
 \left \lceil -\frac{1}{\tau}W_{-1}(-\tau) -1 \right \rceil&\leq 
\left \lceil\frac{1}{\tau}\left(1+\sqrt{2(-\ln(\tau)-1)}+(-\ln(\tau)-1)\right )-1\right\rceil,\\
 & = 
\left \lceil\frac{1}{\tau}\left(\sqrt{-2(\ln(\tau)+1)}-\ln(\tau)\right )-1\right\rceil\leq \left \lceil 2\frac{1}{\tau} \ln\left (\frac{1}{\tau}\right )-1\right \rceil,
 \end{aligned}
\]
where the last inequality follows from the trivial bound $\sqrt{-2(u+1)}\leq -u$ for any $u\leq -1$. Observe that the last quantity is at least $1$ for all $\tau \in (0,e^{-1})$.

