For the sake of completeness, we recall how a standard argument allows to transfer the variance reduction into a bound on $\sigma_n$. 

For a given iteration $n$, let $\xi^n_{1},\ldots,\xi^n_{k_n}$ be $k_n$ independent samples of the distribution $\mathcal D_{x^{n-1}}$ and let $e_n^2=\EE (||\tilde{T}(x^{n-1}, \xi^n_{1}) - T x^{n-1}||_2^2)$ be the variance of the error term of one query. Then
\begin{equation}
\sigma_n^2=\EE(\norm{U_n})^2 \le \frac{\mu^2}{k_n^2} \EE\left(\norm{\sum \nolimits_{j=1}^{k_n} \tilde{T}(x^{n-1}, \xi^n_{j}) - Tx^{n-1} }^2_2\right) \le \frac{\mu^2}{k_n}e_n^2,
\label{minibatch}
\end{equation}
where we have use Jensen's inequality, sample independence, and the equivalence between the norms. We observe that $\EE(\norm{U_n})$ scales by a factor $\frac{\mu}{\sqrt{k_n}}$ compared to $e_n$.

\begin{proof}
Recall that $\sigma_0=\beta_0=0$ and let $\kappa_n= \norm{Tx^n-x^0}$. We start by observing that the (random) sequence $(P_n)_n$ defined inductively as $P_0=0$ and
\[ P_n=
\kappa_{n-1} (\beta_n-\beta_{n-1})+\beta_{n-1} P_{n-1}+\beta_n\norm{U_n}+\beta_{n-1}\norm{U_{n-1}},\,\,  n\geq 1,
\]
is such that $\norm{x^n-x^{n-1}}\leq P_n$ for all $n \in \NN$. Indeed, for the first term we write
\[
\norm{x^1-x^0}= \beta_1\norm{x^0 -Tx^0 + U_1} \leq \kappa_0 (\beta_1-\beta_0) + \beta_1 \norm{U_1}=P_1.
\]
From the definition of \eqref{halpern}, using again the triangular inequality, the nonexpansivity of $T$, and the induction hypothesis, we have that for $n \geq 2$,
\begin{equation*}
\begin{aligned}
\!\!\norm{x^n\!-\!x^{n-1}} &=\norm{(1\!-\! \beta_{n}) x^0 + \beta_n(Tx^{n-1} +U_n)-(1\!-\!\beta_{n-1})x^0 \!-\! \beta_{n-1}(Tx^{n-2} +U_{n\!-\!1})}\\
&=\norm{(\beta_{n}\!-\!\beta_{n-1})(T x^{n-1}\!-\!x^0)\! + \!\beta_{n-1}(Tx^{n-1}\!\!-Tx^{n-2}) \!+\!\beta_{n} U_n\!-\!\beta_{n-1}U_{n-1}} \\
&\leq (\beta_n-\beta_{n-1})\norm{T x^{n-1}\!-\!x^0}\!+\! \beta_{n-1}\norm{x^{n-1}\!-\!x^{n-2}}\!+\!\beta_n\norm{U_{n}}\!+\!\beta_{n-1}\norm{U_{n-1}} \\
&\le \kappa_{n-1} (\beta_n-\beta_{n-1})+\beta_{n-1} P_{n-1}+\beta_n\norm{U_{n}}\!+\!\beta_{n-1}\norm{U_{n-1}}=P_n.
\end{aligned}
\end{equation*}

Then, it follows that $P_n$ can be computed explicitly as
\[
P_n=\sum_{i=1}^{n}B_i^{n-1} \left ( \kappa_{i-1}(\beta_i -\beta_{i-1}) + \beta_i\norm{U_{i}}+\beta_{i-1}\norm{U_{i-1}} \right ).
\]
where we used the convention $B^{n-1}_n = 1$. Now, casting \eqref{halpern} as
   \[
    x^{n} - Tx^n = (1-\beta_{n})(x^0-Tx^{n}) + \beta_{n} (Tx^{n-1}-Tx^n + U_{n}), \quad \forall \, n \geq 1,
   \]
we get that 
\begin{equation}\label{eq:residual}
\begin{aligned}
\!\!\!\norm{x^n-\!Tx^n} & \!\!=\! \!\norm{(1\!-\!\beta_n)(x^0-Tx^{n})+\beta_n(Tx^{n-1}-Tx^n+U_n )} \\
&\le \kappa_n (1-\beta_n) +  \beta_n  \norm{x^n-x^{n-1}}+ \beta_n\norm{U_n} \\
&\leq \kappa_n(1-\beta_n) +  \beta_n  P_n+ \beta_n\norm{U_n},\\
& = \kappa_n(1-\!\beta_n)\! +\! \\
&+\sum_{i=1}^{n}B_i^{n}\left ( \!\kappa_{i-1}(\beta_i -\beta_{i-1})\! + \!\beta_i\norm{U_i}\!\!+\!\!\beta_{i-1}\norm{U_{i-1}} \!\right )+ \beta_n\norm{U_n}
\end{aligned}
\end{equation}
where we used that $B^n_i = \beta_nB^{n-1}_i$ for every $i=1,...,n$ and that $B^{n-1}_{n} = 1$. Taking expectations in the expression above, and using that $\sigma_i = \EE(\norm{U_i})$, we obtain
\begin{equation*}
\begin{aligned}
\EE(\norm{x^n\!\!-\!\!Tx^n}) &\leq \EE(\kappa_n)(1-\!\beta_n)+ \sum_{i=1}^{n}B_i^{n}\left ( \EE(\kappa_{i-1})(\beta_i -\beta_{i-1})\! + \!\beta_i\sigma_i +\beta_{i\!-\!1}\sigma_{i-1} \!\right )\!+\! \beta_n\sigma_n. 
\end{aligned}
\end{equation*}
The conclusion follows from the fact that $\sup_{n\geq 0} \EE(\kappa_n) \leq \overline \kappa$.
\end{proof}

\begin{lemma} \label{lem:kappa}
{\em Let $T$ be nonexpansive and $(x^n)_n$ be the sequence generated by \eqref{halpern}. Recalling the notation \eqref{notation_beta_sigma}, it holds:
\begin{itemize}
    \item[$(i)$] If $T$ has bounded range i.e. there exist a constant $M>0$ such that $\norm{Tx} \le M$ for all $x\in \RR^d$, then the condition \eqref{H1} holds with $\bar \kappa = M + \norm{x^0}$.
    \item[$(ii)$] If the sequences $(\beta_n)_n$ and $(\sigma_n)_n$ satisfies
    \begin{equation}\label{H2}\tag{$\textsc{H}_2$}
    \sup_{n\ge 1}\sum_{i=1}^n B_i^n\sigma_i\leq S < +\infty,,
