  &\le\frac{\bar{\kappa}}{N\!+\!1}\sum_{n=0}^{N}\frac{1}{n\!+\!1}+\frac{2}{N\!+\!1}\sum_{n=1}^N n\sigma_n - \frac{1}{N+1}\sum_{n=1}^N \sigma_n,
\end{aligned}
\end{equation}
where we have used in the second line that $\sigma_0=0$. We observe that the first term $\tilde{O}(1/N)$ and the second also is by hypothesis. Therefore, $\EE(\norm{x^N-Tx^N}) = \tilde{O}(1/N)$, and $\EE(\norm{ x^N-Tx^N }) \le \varepsilon$, for all $N \geq \bar N= \tilde{O}(\varepsilon^{-1})$ iterations as claimed.
\end{proof}

