&\leq (\beta_n-\beta_{n-1})\norm{T x^{n-1}\!-\!x^0}\!+\! \beta_{n-1}\norm{x^{n-1}\!-\!x^{n-2}}\!+\!\beta_n\norm{U_{n}}\!+\!\beta_{n-1}\norm{U_{n-1}} \\
&\le \kappa_{n-1} (\beta_n-\beta_{n-1})+\beta_{n-1} P_{n-1}+\beta_n\norm{U_{n}}\!+\!\beta_{n-1}\norm{U_{n-1}}=P_n.
\end{aligned}
\end{equation*}

we get that 
\begin{equation}\label{eq:residual}
\begin{aligned}
\!\!\!\norm{x^n-\!Tx^n} & \!\!=\! \!\norm{(1\!-\!\beta_n)(x^0-Tx^{n})+\beta_n(Tx^{n-1}-Tx^n+U_n )} \\
&\le \kappa_n (1-\beta_n) +  \beta_n  \norm{x^n-x^{n-1}}+ \beta_n\norm{U_n} \\
&\leq \kappa_n(1-\beta_n) +  \beta_n  P_n+ \beta_n\norm{U_n},\\
& = \kappa_n(1-\!\beta_n)\! +\! \\
&+\sum_{i=1}^{n}B_i^{n}\left ( \!\kappa_{i-1}(\beta_i -\beta_{i-1})\! + \!\beta_i\norm{U_i}\!\!+\!\!\beta_{i-1}\norm{U_{i-1}} \!\right )+ \beta_n\norm{U_n}
\end{aligned}
\end{equation}

where we used that $B^n_i = \beta_nB^{n-1}_i$ for every $i=1,...,n$ and that $B^{n-1}_{n} = 1$. Taking expectations in the expression above, and using that $\sigma_i = \EE(\norm{U_i})$, we obtain
\begin{equation*}
\begin{aligned}
\EE(\norm{x^n\!\!-\!\!Tx^n}) &\leq \EE(\kappa_n)(1-\!\beta_n)+ \sum_{i=1}^{n}B_i^{n}\left ( \EE(\kappa_{i-1})(\beta_i -\beta_{i-1})\! + \!\beta_i\sigma_i +\beta_{i\!-\!1}\sigma_{i-1} \!\right )\!+\! \beta_n\sigma_n. 
\end{aligned}
\end{equation*}
The conclusion follows from the fact that $\sup_{n\geq 0} \EE(\kappa_n) \leq \overline \kappa$.
\end{proof}

